1259	new file mode 100644
1260	index 0000000..8240485
1261	--- /dev/null
1262	+++ b/firmware/after_dark_sprites.py
1263	@@ -0,0 +1,56 @@
1264	+"""PlatformIO pre-build script: extracts the Flying Toasters sprites from a
1265	+user-supplied After Dark disk image into toaster_sprites.h in the build
1266	+directory. The image is never committed. When it is absent the hack is left
1267	+out (HAVE_AFTER_DARK_TOASTERS stays undefined). Needs uv, because machfs is
1268	+not in PlatformIO's Python."""
1269	+
1270	+import hashlib
1271	+import os
1272	+import re
1273	+import shutil
1274	+import subprocess
1275	+import sys
1276	+from pathlib import Path
1277	+
1278	+Import("env")  # noqa: F821
1279	+
1280	+repo = Path(env["PROJECT_DIR"]).parent  # noqa: F821
1281	+image = Path(os.environ.get("AFTER_DARK_IMAGE") or "vendor/after-dark-v2.0v-800k")
1282	+if not image.is_absolute():
1283	+    image = repo / image
1284	+tool = repo / "tools" / "after_dark_sprites.py"
1285	+generated = Path(env.subst("$BUILD_DIR")) / "generated"  # noqa: F821
1286	+header = generated / "after_dark" / "toaster_sprites.h"
1287	+
1288	+if not image.is_file():
1289	+    print(f"ad-flyingtoasters: no After Dark disk image at {image}; left out")
1290	+else:
1291	+    image_sha = hashlib.sha256(image.read_bytes()).hexdigest()
1292	+    recorded = (
1293	+        re.search(r"sha256 ([0-9a-f]{64})", header.read_text().split("\n", 1)[0])
1294	+        if header.exists()
1295	+        else None
1296	+    )
1297	+    if (
1298	+        recorded is None
1299	+        or recorded.group(1) != image_sha
1300	+        or header.stat().st_mtime < image.stat().st_mtime
1301	+        or header.stat().st_mtime < tool.stat().st_mtime
1302	+    ):
1303	+        uv = shutil.which("uv")
1304	+        if not uv:
1305	+            sys.exit("after_dark_sprites.py needs uv on PATH to read the disk image")
1306	+        header.parent.mkdir(parents=True, exist_ok=True)
1307	+        result = subprocess.run(
1308	+            [uv, "run", str(tool), str(image), "-o", str(header)],
1309	+            capture_output=True,
1310	+            text=True,
1311	+            check=False,
1312	+        )
1313	+        if result.returncode != 0:
1314	+            sys.exit(
1315	+                result.stderr.strip() or f"{tool.name} failed ({result.returncode})"
1316	+            )
1317	+    env.Append(  # noqa: F821
1318	+        CPPPATH=[str(generated)], CPPDEFINES=["HAVE_AFTER_DARK_TOASTERS"]
1319	+    )
