1388	index 0000000..98b06cf
1389	--- /dev/null
1390	+++ b/firmware/src/hacks/ad_flyingtoasters/ad_flyingtoasters.c
1391	@@ -0,0 +1,150 @@
1392	+/* ad-flyingtoasters: a recreation of Flying Toasters from Berkeley Systems'
1393	+ * After Dark 2.0, (c) 1990-91 Berkeley Systems, by Jack Eastman, Bruce
1394	+ * Burkhalter, Patrick Beard and Tomoya Ikeda. This code is ours (MIT); the
1395	+ * art is read at build time from the user's own copy of the After Dark disk
1396	+ * (https://archive.org/details/after-dark-2.0v-800k) and never committed. */
1397	+
1398	+#ifdef HAVE_AFTER_DARK_TOASTERS
1399	+
1400	+#include <stdint.h>
1401	+#include <stdio.h>
1402	+#include <stdlib.h>
1403	+#include <string.h>
1404	+
1405	+#include "after_dark/toaster_sprites.h"
1406	+#include "core/canvas.h"
1407	+#include "hacks/ad_flyingtoasters/ad_sim.h"
1408	+#include "hacks/ad_flyingtoasters/ad_sprites.h"
1409	+#include "runner/hack_entry.h"
1410	+
1411	+#ifdef ESP_PLATFORM
1412	+#include <esp_random.h>
1413	+#endif
1414	+
1415	+#if defined(AD_TOASTERS_ART) && AD_TOASTERS_ART != 0 && AD_TOASTERS_ART != 1
1416	+#error "AD_TOASTERS_ART must be 0 (1-bit) or 1 (colour)"
1417	+#endif
1418	+#if defined(AD_TOASTERS_DONENESS) && AD_TOASTERS_DONENESS != 0 && \
1419	+    AD_TOASTERS_DONENESS != 1 && AD_TOASTERS_DONENESS != 2
1420	+#error "AD_TOASTERS_DONENESS must be 0 (light), 1 (medium) or 2 (dark)"
1421	+#endif
1422	+
1423	+#define AD_SPRITES 5
1424	+#define AD_COUNT 10
1425	+
1426	+typedef struct {
1427	+  Display *dpy;
1428	+  Window window;
1429	+  GC gc;
1430	+  XImage *sprite[AD_SPRITES];
1431	+  AdSim sim;
1432	+} State;
1433	+
1434	+static const char *const ad_flyingtoasters_defaults[] = {".background: black", 0};
1435	+
1436	+/* random() on the device replays the same sequence after every boot, so the
1437	+ * picks take real entropy there; host builds (tests, dump) keep random() so
1438	+ * their frames repeat. */
1439	+static uint32_t ad_entropy(void) {
1440	+#ifdef ESP_PLATFORM
1441	+  return esp_random();
1442	+#else
1443	+  return (uint32_t)random();
1444	+#endif
1445	+}
1446	+
1447	+static void ad_flyingtoasters_free(Display *dpy, Window window, void *closure);
1448	+
1449	+static XImage *make_sprite(Display *dpy, const unsigned char *rgb) {
1450	+  XImage *im = XCreateImage(dpy, NULL, 16, ZPixmap, 0, NULL, AD_RECT, AD_RECT, 16, 0);
1451	+  if (!im) return NULL;
1452	+  uint16_t *px = malloc(AD_RECT * AD_RECT * sizeof *px);
1453	+  if (!px) {
1454	+    XDestroyImage(im);
1455	+    return NULL;
1456	+  }
1457	+  ad_build_sprite(rgb, px);
1458	+  /* XPutImage copies image pixels as they are, and the canvas keeps RGB565
1459	+   * with its bytes swapped (xshim.h's comment saying it swaps is stale). */
1460	+  for (int i = 0; i < AD_RECT * AD_RECT; i++) px[i] = px_swap(px[i]);
1461	+  im->data = (char *)px;
1462	+  return im;
1463	+}
1464	+
1465	+static void blit(void *ctx, const AdRect *r, int sprite) {
1466	+  State *st = ctx;
1467	+  XPutImage(st->dpy, st->window, st->gc, st->sprite[sprite], 0, 0, r->left, r->top,
1468	+            AD_RECT, AD_RECT);
1469	+}
1470	+
1471	+static void *ad_flyingtoasters_init(Display *dpy, Window window) {
1472	+  State *st = calloc(1, sizeof *st);
1473	+  if (!st) return NULL;
1474	+  st->dpy = dpy;
1475	+  st->window = window;
1476	+  st->gc = XCreateGC(dpy, window, 0, NULL);
1477	+
1478	+  AdChoice pick = ad_choose(ad_entropy());
1479	+#ifdef AD_TOASTERS_ART
1480	+  pick.colour = AD_TOASTERS_ART;
1481	+#endif
1482	+#ifdef AD_TOASTERS_DONENESS
1483	+  pick.doneness = (AdDoneness)AD_TOASTERS_DONENESS;
1484	+#endif
1485	+
1486	+  unsigned char *rgb = malloc(64 * 64 * 3);
1487	+  if (!rgb) {
1488	+    ad_flyingtoasters_free(dpy, window, st);
1489	+    return NULL;
1490	+  }
1491	+  for (int s = 0; s < AD_SPRITES; s++) {
1492	+    if (pick.colour) {
1493	+      memcpy(rgb, ad_colour_rgb[s], 64 * 64 * 3);
1494	+      if (s == 4) ad_apply_doneness(rgb, 64 * 64, pick.doneness);
1495	+    } else {
1496	+      ad_expand_mono(ad_mono_bits[s], rgb);
1497	+    }
1498	+    st->sprite[s] = make_sprite(dpy, rgb);
1499	+    if (!st->sprite[s]) {
1500	+      free(rgb);
1501	+      ad_flyingtoasters_free(dpy, window, st);
1502	+      return NULL;
1503	+    }
1504	+  }
1505	+  free(rgb);
1506	+
1507	+  static const char *const doneness[] = {"light", "medium", "dark"};
1508	+  fprintf(stderr, "ad-flyingtoasters: %s, doneness=%s\n",
1509	+          pick.colour ? "colour" : "1-bit", doneness[pick.doneness]);
1510	+
1511	+  XWindowAttributes xgwa;
1512	+  XGetWindowAttributes(dpy, window, &xgwa);
1513	+  AdRect bounds = {0, 0, xgwa.height, xgwa.width};
1514	+  ad_sim_init(&st->sim, bounds, AD_COUNT, random);
1515	+  ad_sim_draw_all(&st->sim, blit, st);
1516	+  return st;
1517	+}
1518	+
1519	+static unsigned long ad_flyingtoasters_draw(Display *dpy, Window window, void *closure) {
1520	+  (void)dpy;
1521	+  (void)window;
1522	+  State *st = closure;
1523	+  if (st) ad_sim_step(&st->sim, blit, st);
1524	+  return 33333;
1525	+}
1526	+
1527	+static void ad_flyingtoasters_free(Display *dpy, Window window, void *closure) {
1528	+  (void)window;
1529	+  State *st = closure;
1530	+  if (!st) return;
1531	+  for (int s = 0; s < AD_SPRITES; s++)
1532	+    if (st->sprite[s]) XDestroyImage(st->sprite[s]);
1533	+  if (st->gc) XFreeGC(dpy, st->gc);
1534	+  free(st);
1535	+}
1536	+
1537	+const HackEntry ad_flyingtoasters_hack = {
1538	+    "ad-flyingtoasters", ad_flyingtoasters_defaults, ad_flyingtoasters_init,
1539	+    ad_flyingtoasters_draw, ad_flyingtoasters_free};
1540	+
1541	+#endif
