1543	new file mode 100644
1544	index 0000000..8848d33
1545	--- /dev/null
1546	+++ b/firmware/src/hacks/ad_flyingtoasters/ad_sim.c
1547	@@ -0,0 +1,149 @@
1548	+#include "ad_sim.h"
1549	+
1550	+#include <stdlib.h>
1551	+
1552	+#define TRIES 4
1553	+
1554	+static AdRect offset(AdRect r, int dh, int dv) {
1555	+  r.left += dh;
1556	+  r.right += dh;
1557	+  r.top += dv;
1558	+  r.bottom += dv;
1559	+  return r;
1560	+}
1561	+
1562	+static int intersects(const AdRect *a, const AdRect *b) {
1563	+  return a->left < b->right && b->left < a->right && a->top < b->bottom && b->top < a->bottom;
1564	+}
1565	+
1566	+static long rnd_mod(const AdSim *sim, long k) { return labs(sim->rnd() % k); }
1567	+
1568	+static AdRect random_inside_rect(const AdSim *sim) {
1569	+  int w = sim->bounds.right - sim->bounds.left;
1570	+  int h = sim->bounds.bottom - sim->bounds.top;
1571	+  AdRect r;
1572	+  r.top = sim->bounds.top + (int)rnd_mod(sim, h - AD_RECT);
1573	+  r.left = sim->bounds.left + (int)rnd_mod(sim, w - AD_RECT);
1574	+  r.bottom = r.top + AD_RECT;
1575	+  r.right = r.left + AD_RECT;
1576	+  return r;
1577	+}
1578	+
1579	+static AdRect random_edge_rect(const AdSim *sim) {
1580	+  int w = sim->bounds.right - sim->bounds.left;
1581	+  int h = sim->bounds.bottom - sim->bounds.top;
1582	+  AdRect r;
1583	+  if (sim->rnd() % 2 != 0) {
1584	+    r.bottom = sim->bounds.top;
1585	+    r.left = sim->bounds.left + (int)rnd_mod(sim, w);
1586	+    r.top = r.bottom - AD_RECT;
1587	+    r.right = r.left + AD_RECT;
1588	+  } else {
1589	+    r.left = sim->bounds.right;
1590	+    r.top = sim->bounds.top + (int)rnd_mod(sim, h);
1591	+    r.right = r.left + AD_RECT;
1592	+    r.bottom = r.top + AD_RECT;
1593	+  }
1594	+  return r;
1595	+}
1596	+
1597	+int ad_sim_collision(const AdSim *sim, int i, AdRect cand, int *dv, int *dh) {
1598	+  for (int k = 0; k < sim->n; k++) {
1599	+    const AdFlyer *o = &sim->f[k];
1600	+    if (k == i || !o->live || !intersects(&o->r, &cand)) continue;
1601	+    int dl = o->r.left - cand.left;
1602	+    int dt = o->r.top - cand.top;
1603	+    if (abs(dt) < abs(dl)) {
1604	+      *dv = -1;
1605	+      *dh = 0;
1606	+    } else {
1607	+      *dv = 0;
1608	+      *dh = cand.top < o->r.top ? -1 : 1;
1609	+    }
1610	+    return 1;
1611	+  }
1612	+  return 0;
1613	+}
1614	+
1615	+static void create_flyer(AdSim *sim, int i) {
1616	+  AdRect r = {0, 0, 0, 0};
1617	+  int placed = 0;
1618	+  for (int t = 0; t < TRIES && !placed; t++) {
1619	+    r = sim->running ? random_edge_rect(sim) : random_inside_rect(sim);
1620	+    int dv, dh;
1621	+    placed = !ad_sim_collision(sim, i, r, &dv, &dh);
1622	+  }
1623	+  if (!placed) return;
1624	+  long roll = rnd_mod(sim, 100);
1625	+  AdFlyer *f = &sim->f[i];
1626	+  f->live = 1;
1627	+  f->toast = roll >= 75;
1628	+  f->speed = f->toast ? 1 : roll >= 50 ? 3 : roll >= 25 ? 2 : 1;
1629	+  f->frame = 0;
1630	+  f->flap_down = 0;
1631	+  f->r = r;
