1633	+
1634	+void ad_sim_init(AdSim *sim, AdRect bounds, int n, long (*rnd)(void)) {
1635	+  if (n > AD_MAX_FLYERS) n = AD_MAX_FLYERS;
1636	+  if (n < 0) n = 0;
1637	+  for (int i = 0; i < AD_MAX_FLYERS; i++) sim->f[i] = (AdFlyer){0};
1638	+  sim->bounds = bounds;
1639	+  sim->n = n;
1640	+  sim->rnd = rnd;
1641	+  sim->running = 0;
1642	+  for (int i = 0; i < n; i++) create_flyer(sim, i);
1643	+  sim->running = 1;
1644	+}
1645	+
1646	+static void draw_flyer(AdFlyer *f, AdDrawFn draw, void *ctx) {
1647	+  draw(ctx, &f->r, f->toast ? 4 : f->frame);
1648	+  if (f->toast) return;
1649	+  if (f->flap_down) {
1650	+    if (f->frame == 0) {
1651	+      f->frame = 1;
1652	+      f->flap_down = 0;
1653	+    } else {
1654	+      f->frame--;
1655	+    }
1656	+  } else if (f->frame == 3) {
1657	+    f->frame = 2;
1658	+    f->flap_down = 1;
1659	+  } else {
1660	+    f->frame++;
1661	+  }
1662	+}
1663	+
1664	+void ad_sim_draw_all(AdSim *sim, AdDrawFn draw, void *ctx) {
1665	+  for (int i = 0; i < sim->n; i++) {
1666	+    if (sim->f[i].live) draw_flyer(&sim->f[i], draw, ctx);
1667	+  }
1668	+}
1669	+
1670	+void ad_sim_step(AdSim *sim, AdDrawFn draw, void *ctx) {
1671	+  for (int i = 0; i < sim->n; i++) {
1672	+    if (!sim->f[i].live) create_flyer(sim, i);
1673	+    if (sim->f[i].live) sim->f[i].r = offset(sim->f[i].r, -2, 1);
1674	+  }
1675	+  for (int i = 0; i < sim->n; i++) {
1676	+    AdFlyer *f = &sim->f[i];
1677	+    if (!f->live) continue;
1678	+    if (!intersects(&f->r, &sim->bounds)) {
1679	+      f->live = 0;
1680	+      continue;
1681	+    }
1682	+    int s = f->speed - 1;
1683	+    if (s > 0) {
1684	+      AdRect cand = offset(f->r, -2 * s, s);
1685	+      int dv, dh;
1686	+      if (ad_sim_collision(sim, i, cand, &dv, &dh)) {
1687	+        cand = offset(f->r, dh, -2 * dv);
1688	+        int dv2, dh2;
1689	+        if (!ad_sim_collision(sim, i, cand, &dv2, &dh2)) f->r = cand;
1690	+      } else {
1691	+        f->r = cand;
1692	+      }
1693	+    }
1694	+    draw_flyer(f, draw, ctx);
1695	+  }
1696	+}
