1755	+void ad_apply_doneness(unsigned char *rgb, int pixels, AdDoneness d) {
1756	+  static const int k[3][3] = {{0, 0, 0}, {79, 79, 79}, {127, 111, 111}};
1757	+  if (d == AD_DONE_LIGHT) return;
1758	+  for (int i = 0; i < pixels; i++) {
1759	+    for (int c = 0; c < 3; c++) {
1760	+      int v = rgb[i * 3 + c] - k[d][c];
1761	+      rgb[i * 3 + c] = (unsigned char)(v > 0 ? v : 0);
1762	+    }
1763	+  }
1764	+}
1765	+
1766	+void ad_expand_mono(const unsigned char bits[512], unsigned char rgb[64 * 64 * 3]) {
1767	+  for (int y = 0; y < 64; y++) {
1768	+    for (int x = 0; x < 64; x++) {
1769	+      int set = (bits[y * 8 + (x >> 3)] >> (7 - (x & 7))) & 1;
1770	+      unsigned char v = set ? 0 : 255;
1771	+      unsigned char *p = &rgb[(y * 64 + x) * 3];
1772	+      p[0] = p[1] = p[2] = v;
1773	+    }
1774	+  }
1775	+}
1776	+
1777	+void ad_build_sprite(const unsigned char rgb[64 * 64 * 3], uint16_t out[70 * 70]) {
1778	+  for (int i = 0; i < 70 * 70; i++) out[i] = 0;
1779	+  for (int y = 0; y < 64; y++) {
1780	+    for (int x = 0; x < 64; x++) {
1781	+      const unsigned char *p = &rgb[(y * 64 + x) * 3];
1782	+      out[(y + 6) * 70 + x] = (uint16_t)(((p[0] >> 3) << 11) | ((p[1] >> 2) << 5) | (p[2] >> 3));
1783	+    }
1784	+  }
1785	+}
