+typedef enum { AD_DONE_LIGHT, AD_DONE_MEDIUM, AD_DONE_DARK } AdDoneness;
+typedef struct {
+  int colour;
+  AdDoneness doneness;
+} AdChoice;
+
+AdChoice ad_choose(uint32_t r); /* bit 0: colour; (r >> 1) % 3: doneness */
